53: /**
54:  * Check the 2FA status of the currently signed-in user.
55:  *
56:  * When 2FA is not set up, the result will include data required to start the setup.
57:  */
58: export async function status (req: Request, res: Response) {
59:   try {
60:     const data = security.authenticatedUsers.from(req)
61:     if (!data) {
62:       throw new Error('You need to be logged in to see this')
63:     }
64:     const { data: user } = data
65: 
66:     if (user.totpSecret === '') {
67:       const secret = generateSecret()
68: 
69:       res.json({
70:         setup: false,
71:         secret,
72:         email: user.email,
73:         setupToken: security.authorize({
74:           secret,
75:           type: 'totp_setup_secret'
76:         })
77:       })
78:     } else {
79:       res.json({
80:         setup: true
81:       })
82:     }
83:   } catch (error) {
84:     res.status(401).send()
85:   }
86: }
87: 
88: /**
89:  * Sets Up 2FA for a User
90:  * Requires 3 params:
91:  * 1. The Users Password as a confirmation.
92:  * 2. A Setup token. This is returned by the status endpoint.
93:  *    This contains a signed TOTP secret to ensure that the secret
94:  *    was generated by the server and wasn't tampered with by the client
95:  * 3. The first TOTP Token, generated by the TOTP App. (e.g. Google Authenticator)
96:  */
97: export async function setup (req: Request, res: Response) {
98:   try {
99:     const data = security.authenticatedUsers.from(req)
100:     if (!data) {
101:       throw new Error('Need to login before setting up 2FA')
102:     }
103:     const { data: user } = data
104: 
105:     const { password, setupToken, initialToken } = req.body
106: 
107:     if (user.password !== security.hash(password)) {
108:       throw new Error('Password doesnt match stored password')
109:     }
110: 
111:     if (user.totpSecret !== '') {
112:       throw new Error('User has 2fa already setup')
113:     }
114: 
115:     const { secret, type } = security.verify(setupToken) && security.decode(setupToken)
116:     if (type !== 'totp_setup_secret') {
117:       throw new Error('SetupToken is of wrong type')
118:     }
119:     if (!verifySync({ secret, token: initialToken, epochTolerance: 30 }).valid) {
120:       throw new Error('Initial token doesnt match the secret from the setupToken')
121:     }
122: 
123:     // Update db model and cached object
124:     const userModel = await UserModel.findByPk(user.id)
125:     if (userModel == null) {
126:       throw new Error('No such user found!')
127:     }
128: 
129:     userModel.totpSecret = secret
130:     await userModel.save()
131:     security.authenticatedUsers.updateFrom(req, utils.queryResultToJson(userModel))
132: 
133:     res.status(200).send()
134:   } catch (error) {
135:     res.status(401).send()
136:   }
137: }
138: 
139: /**
140:  * Disables 2fa for the current user
141:  */
142: export async function disable (req: Request, res: Response) {
143:   try {
144:     const data = security.authenticatedUsers.from(req)
145:     if (!data) {
146:       throw new Error('Need to login before setting up 2FA')
147:     }
148:     const { data: user } = data
