16: export function upgradeToDeluxe () {
17:   return async (req: Request, res: Response, next: NextFunction) => {
18:     try {
19:       const user = await UserModel.findOne({ where: { id: req.body.UserId, role: security.roles.customer } })
20:       if (user == null) {
21:         res.status(400).json({ status: 'error', error: 'Something went wrong. Please try again!' })
22:         return
23:       }
24:       if (req.body.paymentMode === 'wallet') {
25:         const wallet = await WalletModel.findOne({ where: { UserId: req.body.UserId } })
26:         if ((wallet != null) && wallet.balance < 49) {
27:           res.status(400).json({ status: 'error', error: 'Insuffienct funds in Wallet' })
28:           return
29:         } else {
30:           await WalletModel.decrement({ balance: 49 }, { where: { UserId: req.body.UserId } })
31:         }
32:       }
33: 
34:       if (req.body.paymentMode === 'card') {
35:         const card = await CardModel.findOne({ where: { id: req.body.paymentId, UserId: req.body.UserId } })
36:         if ((card == null) || card.expYear < new Date().getFullYear() || (card.expYear === new Date().getFullYear() && card.expMonth - 1 < new Date().getMonth())) {
37:           res.status(400).json({ status: 'error', error: 'Invalid Card' })
38:           return
39:         }
40:       }
41: 
42:       try {
43:         const updatedUser = await user.update({ role: security.roles.deluxe, deluxeToken: security.deluxeToken(user.email) })
44:         challengeUtils.solveIf(challenges.freeDeluxeChallenge, () => {
45:           return security.verify(utils.jwtFrom(req)) && req.body.paymentMode !== 'wallet' && req.body.paymentMode !== 'card'
46:         })
47:         const userWithStatus = utils.queryResultToJson(updatedUser)
48:         const updatedToken = security.authorize(userWithStatus)
49:         security.authenticatedUsers.put(updatedToken, userWithStatus)
50:         res.status(200).json({ status: 'success', data: { confirmation: 'Congratulations! You are now a deluxe member!', token: updatedToken } })
51:       } catch (error) {
52:         res.status(400).json({ status: 'error', error: 'Something went wrong. Please try again!' })
53:       }
54:     } catch (err: unknown) {
55:       res.status(400).json({ status: 'error', error: 'Something went wrong: ' + utils.getErrorMessage(err) })
56:     }
57:   }
58: }
