19: export function addBasketItem () {
20:   return async (req: Request, res: Response, next: NextFunction) => {
21:     const result = utils.parseJsonCustom((req as RequestWithRawBody).rawBody)
22:     const productIds = []
23:     const basketIds = []
24:     const quantities = []
25: 
26:     for (let i = 0; i < result.length; i++) {
27:       if (result[i].key === 'ProductId') {
28:         productIds.push(result[i].value)
29:       } else if (result[i].key === 'BasketId') {
30:         basketIds.push(result[i].value)
31:       } else if (result[i].key === 'quantity') {
32:         quantities.push(result[i].value)
33:       }
34:     }
35: 
36:     const user = security.authenticatedUsers.from(req)
37:     if (user && basketIds[0] && basketIds[0] !== 'undefined' && Number(user.bid) != Number(basketIds[0])) { // eslint-disable-line eqeqeq
38:       res.status(401).send('{\'error\' : \'Invalid BasketId\'}')
39:     } else {
40:       const basketItem = {
41:         ProductId: productIds[productIds.length - 1],
42:         BasketId: basketIds[basketIds.length - 1],
43:         quantity: quantities[quantities.length - 1]
44:       }
45:       challengeUtils.solveIf(challenges.basketManipulateChallenge, () => { return user && basketItem.BasketId && basketItem.BasketId !== 'undefined' && user.bid != basketItem.BasketId }) // eslint-disable-line eqeqeq
46: 
47:       const basketItemInstance = BasketItemModel.build(basketItem)
48:       try {
49:         const addedBasketItem = await basketItemInstance.save()
50:         res.json({ status: 'success', data: addedBasketItem })
51:       } catch (error) {
52:         next(error)
53:       }
54:     }
55:   }
56: }
