85: async function quantityCheck (req: Request, res: Response, next: NextFunction, id: number, quantity: number) {
86:   const product = await QuantityModel.findOne({ where: { ProductId: id } })
87:   if (product == null) {
88:     throw new Error('No such product found!')
89:   }
90: 
91:   // is product limited per user and order, except if user is deluxe?
92:   if (!product.limitPerUser || (product.limitPerUser && product.limitPerUser >= quantity) || security.isDeluxe(req)) {
93:     if (product.quantity >= quantity) { // enough in stock?
94:       next()
95:     } else {
96:       res.status(400).json({ error: res.__('We are out of stock! Sorry for the inconvenience.') })
97:     }
98:   } else {
99:     res.status(400).json({ error: res.__('You can order only up to {{quantity}} items of this product.', { quantity: product.limitPerUser.toString() }) })
100:   }
101: }
